int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    struct sctp_association *assoc;
    struct socket *new_sk;
    int ret = -EINVAL;

    assoc = sctp_id2assoc(sk, id);
    if (!assoc)
        return -ENOENT;

    if (!sctp_assoc_can_peeloff(assoc))
        return -EBUSY;

    ret = sock_create(sk->sk_family, sk->sk_type, sk->sk_protocol,
                      &new_sk);
    if (ret < 0)
        return ret;

    sctp_assoc_copy(new_sk, sk, assoc);
    sctp_migrate_assoc(assoc, new_sk);

    *sockp = new_sk;
    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    int ret = -EINVAL;
    struct sctp_association *asoc = NULL;

    /* Retrieve the SCTP association using the provided ID */
    asoc = sctp_id2assoc(sk, id);
    if (!asoc)
        return -ENOENT;

    /* Check if the association is eligible for peeling off */
    if (!asoc->peer.primary_addr_set || asoc->base.sk != sk) {
        return -EINVAL;
    }

    /* Create a new socket */
    struct socket *new_sk = NULL;
    ret = sock_create_kern(current_net, PF_INET, SOCK_STREAM, IPPROTO_SCTP, &new_sk);
    if (ret < 0) {
        return ret;
    }

    /* Copy properties from the original socket */
    ret = sctp_copy_sock(new_sk, sk);
    if (ret < 0) {
        sock_release(new_sk);
        return ret;
    }

    /* Migrate the association to the new socket */
    ret = sctp_migrate_association(sk, new_sk, asoc);
    if (ret < 0) {
        sock_release(new_sk);
        return ret;
    }

    *sockp = new_sk;

    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    struct sctp_association *assoc = sctp_id2assoc(sk, id);
    int ret = -EINVAL;

    if (!assoc)
        return -EINVAL;

    if (!sctp_assoc eligible_for_peeloff(assoc))
        return -EBUSY;

    *sockp = sock_alloc();
    if (!*sockp)
        return -ENOMEM;

    sock_init_data(*sockp, sk);

    if (sctp_migrate_assoc(sk, *sockp, assoc)) {
        sock_release(*sockp);
        return -EFAULT;
    }

    ret = 0;
    return ret;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp)
{
    struct sctp_association *assoc;
    int ret = -EINVAL;

    assoc = sctp_id2assoc(sk, id);
    if (!assoc)
        return -ESRCH;

    if (!sctp_primitive_peeloff(sk, assoc))
        return -EBUSY;

    ret = sock_create_kern(&init_net, PF_INET, SOCK_STREAM, IPPROTO_SCTP, sockp);
    if (ret < 0)
        return ret;

    sctp_copy_sock(*sockp, sk, assoc);
    sctp_assoc_migrate(assoc, *sockp);

    return 0;
}
